import * as zlib from 'zlib';
import * as http from 'http';
import { promisify } from 'util';

const gunzip = promisify(zlib.gunzip);
const inflate = promisify(zlib.inflate);

interface IndexEntry {
  id: string;
  content: string;
  timestamp: number;
}

interface RateLimitState {
  tokens: number;
  lastRefill: number;
  maxTokens: number;
  refillRate: number;
}

class SearchIndexService {
  private index: Map<string, IndexEntry[]> = new Map();
  private rateLimiter: RateLimitState;
  private retryQueue: Array<{ payload: Buffer; attempts: number; encoding: string }> = [];
  private readonly MAX_RETRIES = 3;
  private readonly MAX_COMPRESSED_SIZE = 1024 * 1024; // 1MB compressed limit
  private readonly DECOMPRESSION_RATIO_LIMIT = 100;

  constructor() {
    this.rateLimiter = {
      tokens: 10,
      lastRefill: Date.now(),
      maxTokens: 10,
      refillRate: 2
    };
    setInterval(() => this.processRetryQueue(), 5000);
  }

  private refillTokens(): void {
    const now = Date.now();
    const elapsed = (now - this.rateLimiter.lastRefill) / 1000;
    this.rateLimiter.tokens = Math.min(
      this.rateLimiter.maxTokens,
      this.rateLimiter.tokens + elapsed * this.rateLimiter.refillRate
    );
    this.rateLimiter.lastRefill = now;
  }

  private consumeToken(): boolean {
    this.refillTokens();
    if (this.rateLimiter.tokens >= 1) {
      this.rateLimiter.tokens -= 1;
      return true;
    }
    return false;
  }

  private validateCompressedSize(data: Buffer): boolean {
    return data.length <= this.MAX_COMPRESSED_SIZE;
  }

  private computeDecompressionBudget(compressedSize: number): number {
    // Budget is ratio limit * compressed size
    return this.DECOMPRESSION_RATIO_LIMIT * compressedSize;
  }

  private validateEntries(parsed: unknown): IndexEntry[] {
    if (!Array.isArray(parsed)) {
      throw new Error('Payload must be a JSON array of entries');
    }
    for (const entry of parsed) {
      if (
        entry === null ||
        typeof entry !== 'object' ||
        typeof (entry as IndexEntry).id !== 'string' ||
        typeof (entry as IndexEntry).content !== 'string' ||
        typeof (entry as IndexEntry).timestamp !== 'number'
      ) {
        throw new Error('Invalid entry shape in payload');
      }
    }
    return parsed as IndexEntry[];
  }

  private async decompressWithBudget(
    data: Buffer,
    budget: number,
    encoding: string
  ): Promise<Buffer> {
    // Stream-based decompression with budget enforcement
    return new Promise((resolve, reject) => {
      const decompressor = encoding === 'gzip'
        ? zlib.createGunzip()
        : zlib.createInflate();

      const chunks: Buffer[] = [];
      let totalSize = 0;

      decompressor.on('data', (chunk: Buffer) => {
        totalSize += chunk.length;
        if (totalSize > budget) {
          decompressor.destroy(new Error('Decompression budget exceeded'));
          return;
        }
        chunks.push(chunk);
      });

      decompressor.on('end', () => {
        resolve(Buffer.concat(chunks));
      });

      decompressor.on('error', (err) => {
        reject(err);
      });

      decompressor.write(data);
      decompressor.end();
    });
  }

  async processPayload(compressedData: Buffer, encoding: string): Promise<IndexEntry[]> {
    if (!this.validateCompressedSize(compressedData)) {
      throw new Error('Compressed payload exceeds size limit');
    }

    const budget = this.computeDecompressionBudget(compressedData.length);
    const decompressed = await this.decompressWithBudget(compressedData, budget, encoding);

    const entries = this.validateEntries(JSON.parse(decompressed.toString('utf-8')));
    return entries;
  }

  private async processRetryQueue(): Promise<void> {
    const batch = this.retryQueue.splice(0, 5);
    for (const item of batch) {
      if (item.attempts >= this.MAX_RETRIES) continue;
      try {
        if (!this.consumeToken()) {
          item.attempts++;
          this.retryQueue.push(item);
          continue;
        }
        // On retry, recompute budget using the FULL original payload size
        const budget = this.computeDecompressionBudget(item.payload.length);
        const decompressed = await this.decompressWithBudget(item.payload, budget, item.encoding);
        const entries = this.validateEntries(JSON.parse(decompressed.toString('utf-8')));
        this.addToIndex(entries);
      } catch (e) {
        item.attempts++;
        if (item.attempts < this.MAX_RETRIES) {
          this.retryQueue.push(item);
        }
      }
    }
  }

  async handleRequest(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
    if (!this.consumeToken()) {
      res.writeHead(429);
      res.end(JSON.stringify({ error: 'Rate limited' }));
      return;
    }

    const chunks: Buffer[] = [];
    let totalReceived = 0;
    const MAX_BODY = this.MAX_COMPRESSED_SIZE;
    for await (const chunk of req) {
      totalReceived += (chunk as Buffer).length;
      if (totalReceived > MAX_BODY) {
        res.writeHead(413);
        res.end(JSON.stringify({ error: 'Payload too large' }));
        return;
      }
      chunks.push(chunk as Buffer);
    }
    const body = Buffer.concat(chunks);
    const encoding = req.headers['content-encoding'] || 'gzip';

    try {
      const entries = await this.processPayload(body, encoding as string);
      this.addToIndex(entries);
      res.writeHead(200);
      res.end(JSON.stringify({ indexed: entries.length }));
    } catch (e) {
      // On failure, queue for retry
      this.retryQueue.push({ payload: body, attempts: 0, encoding: encoding as string });
      res.writeHead(202);
      res.end(JSON.stringify({ status: 'queued_for_retry' }));
    }
  }

  private addToIndex(entries: IndexEntry[]): void {
    for (const entry of entries) {
      const tokens = entry.content.toLowerCase().split(/\s+/);
      for (const token of tokens) {
        if (!this.index.has(token)) {
          this.index.set(token, []);
        }
        this.index.get(token)!.push(entry);
      }
    }
  }

  search(query: string): IndexEntry[] {
    const tokens = query.toLowerCase().split(/\s+/);
    const results: Map<string, IndexEntry> = new Map();
    for (const token of tokens) {
      const entries = this.index.get(token) || [];
      for (const entry of entries) {
        results.set(entry.id, entry);
      }
    }
    return Array.from(results.values());
  }
}

const service = new SearchIndexService();
const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/index') {
    service.handleRequest(req, res);
  } else if (req.method === 'GET' && req.url?.startsWith('/search')) {
    const url = new URL(req.url, `http://${req.headers.host}`);
    const q = url.searchParams.get('q') || '';
    const results = service.search(q);
    res.writeHead(200);
    res.end(JSON.stringify(results));
  } else {
    res.writeHead(404);
    res.end();
  }
});

server.listen(3000);
export { SearchIndexService };
